"""ML-DSA keys in OpenBao Transit (mldsa-44/65/87): generated by type, public key
turned from Transit's raw base64 into an RFC 9881 SubjectPublicKeyInfo, signed pure
with no hash_algorithm. A key type the provider cannot name is refused instead of
signed without one.

Transit is a stand-in signing through pyca. A real server runs only when
UCM_TEST_OPENBAO_URL and UCM_TEST_OPENBAO_TOKEN name one (OpenBao 2.5 or later).
"""
import base64
import os
import uuid

import pytest
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ec, mldsa

from services.hsm.base_provider import HsmOperationError
from services.hsm.openbao_provider import OpenBaoProvider
from utils import key_algorithms

pytestmark = pytest.mark.skipif(not key_algorithms.mldsa_supported(), reason='this build has no ML-DSA')

LEVELS = {
    'ML-DSA-44': ('mldsa-44', mldsa.MLDSA44PrivateKey),
    'ML-DSA-65': ('mldsa-65', mldsa.MLDSA65PrivateKey),
    'ML-DSA-87': ('mldsa-87', mldsa.MLDSA87PrivateKey),
}


class _Transit:
    """Answers the Transit calls the provider makes, the way OpenBao does."""

    def __init__(self):
        self.keys, self.requests = {}, []

    def add(self, name, transit_type, key=None):
        self.keys[name] = (transit_type, key)

    def __call__(self, method, path, **kwargs):
        body = kwargs.get('json') or {}
        self.requests.append((method, path, body))
        kind, _, name = path.partition('/')
        if method == 'POST' and kind == 'keys' and '/' not in name:
            # A name it already holds answers success and keeps that key
            if name not in self.keys:
                cls = next(c for t, c in LEVELS.values() if t == body['type'])
                self.add(name, body['type'], cls.generate())
            return {}
        if method == 'GET' and kind == 'keys':
            if name not in self.keys:
                return {}  # what the provider's _api makes of a 404
            transit_type, key = self.keys[name]
            public = (base64.b64encode(key.public_key().public_bytes_raw()).decode()
                      if transit_type.startswith('mldsa') else None)
            return {'data': {'type': transit_type, 'latest_version': 1,
                             'keys': {'1': {'public_key': public}}}}
        if method == 'LIST':
            return {'data': {'keys': list(self.keys)}}
        if method == 'POST' and kind == 'sign':
            _transit_type, key = self.keys[name]
            signature = key.sign(base64.b64decode(body['input']))
            return {'data': {'signature': 'vault:v1:' + base64.b64encode(signature).decode()}}
        raise AssertionError(f'unexpected call {method} {path}')


def _provider():
    provider = OpenBaoProvider({'url': 'http://bao.invalid:8200', 'token': 't'})
    transit = _Transit()
    provider._api = transit
    return provider, transit


def _spki(pem):
    return serialization.load_pem_public_key(pem.encode())


@pytest.mark.parametrize('label', sorted(LEVELS))
def test_generation_asks_for_the_transit_type_and_returns_spki(label):
    provider, transit = _provider()
    info = provider.generate_key(f'pq-{label}', label)
    assert [r[2]['type'] for r in transit.requests if r[0] == 'POST'] == [LEVELS[label][0]]
    assert (info.algorithm, info.key_type) == (label, 'asymmetric')
    assert key_algorithms.label_for_public_key(_spki(info.public_key_pem)) == label
    assert _spki(provider.get_public_key(info.key_identifier)) == _spki(info.public_key_pem)


@pytest.mark.parametrize('existing', ['ML-DSA-65', 'ML-DSA-44'])
def test_generation_refuses_a_name_transit_already_holds(existing):
    provider, transit = _provider()
    held = LEVELS[existing][1].generate()
    transit.add('taken', LEVELS[existing][0], held)
    with pytest.raises(HsmOperationError, match='already exists'):
        provider.generate_key('taken', 'ML-DSA-65')
    assert transit.keys['taken'] == (LEVELS[existing][0], held)
    assert not [r for r in transit.requests if r[0] == 'POST']


@pytest.mark.parametrize('label', sorted(LEVELS))
def test_listing_names_the_level_and_gives_spki(label):
    provider, transit = _provider()
    transit.add('k', LEVELS[label][0], LEVELS[label][1].generate())
    [info] = provider.list_keys()
    assert info.algorithm == label
    assert key_algorithms.label_for_public_key(_spki(info.public_key_pem)) == label


@pytest.mark.parametrize('algorithm', ['ML-DSA-65', None])
def test_sign_sends_no_hash_algorithm(algorithm):
    provider, transit = _provider()
    key = mldsa.MLDSA65PrivateKey.generate()
    transit.add('k', 'mldsa-65', key)
    signature = provider.sign('k', b'tbs', algorithm)
    key.public_key().verify(signature, b'tbs')
    sent = [body for method, path, body in transit.requests if path == 'sign/k']
    assert sent == [{'input': base64.b64encode(b'tbs').decode()}]


@pytest.mark.parametrize('extra', [{'hash_algorithm': 'sha256'}, {'padding': 'pss'}])
def test_sign_refuses_a_digest_or_padding(extra):
    provider, transit = _provider()
    transit.add('k', 'mldsa-65', mldsa.MLDSA65PrivateKey.generate())
    with pytest.raises(HsmOperationError, match='ML-DSA'):
        provider.sign('k', b'tbs', 'ML-DSA-65', **extra)
    assert not [r for r in transit.requests if r[1].startswith('sign/')]


@pytest.mark.parametrize('algorithm', ['whatever', 'EC-BP256', 'SLH-DSA-SHA2-128s'])
def test_a_named_algorithm_it_does_not_know_is_refused_before_any_call(algorithm):
    provider, transit = _provider()
    transit.add('k', 'mldsa-65', mldsa.MLDSA65PrivateKey.generate())
    with pytest.raises(HsmOperationError, match='Unsupported algorithm'):
        provider.sign('k', b'tbs', algorithm)
    assert transit.requests == []


@pytest.mark.parametrize('transit_type', ['slh-dsa-sha2-128s', 'aes256-gcm96', ''])
def test_a_key_type_it_cannot_name_is_refused_not_signed(transit_type):
    provider, transit = _provider()
    transit.add('k', transit_type, ec.generate_private_key(ec.SECP256R1()))
    with pytest.raises(HsmOperationError, match='cannot sign'):
        provider.sign('k', b'tbs')
    assert not [r for r in transit.requests if r[1].startswith('sign/')]


def test_fips_inventory_leaves_ml_dsa_keys_out(monkeypatch):
    import fips_mode
    provider, transit = _provider()
    transit.add('k', 'mldsa-65', mldsa.MLDSA65PrivateKey.generate())
    monkeypatch.setattr(fips_mode, 'enabled', lambda: True)
    assert provider.list_keys() == []


BENCH_URL = os.environ.get('UCM_TEST_OPENBAO_URL')


@pytest.mark.skipif(not BENCH_URL, reason='no OpenBao bench (set UCM_TEST_OPENBAO_URL, '
                    'UCM_TEST_OPENBAO_TOKEN and optionally UCM_TEST_OPENBAO_MOUNT)')
@pytest.mark.parametrize('label', sorted(LEVELS))
def test_real_openbao_generates_exports_and_signs(label):
    provider = OpenBaoProvider({'url': BENCH_URL, 'token': os.environ['UCM_TEST_OPENBAO_TOKEN'],
                                'mount_path': os.environ.get('UCM_TEST_OPENBAO_MOUNT', 'transit')})
    name = f'ucm-pq-test-{label.lower()}-{uuid.uuid4().hex[:8]}'
    with provider:
        info = provider.generate_key(name, label)
        try:
            public = _spki(provider.get_public_key(name))
            assert key_algorithms.label_for_public_key(public) == label
            assert _spki(info.public_key_pem) == public
            public.verify(provider.sign(name, b'tbs', label), b'tbs')
        finally:
            provider.delete_key(name)


@pytest.mark.skipif(not BENCH_URL, reason='no OpenBao bench (set UCM_TEST_OPENBAO_URL, '
                    'UCM_TEST_OPENBAO_TOKEN and optionally UCM_TEST_OPENBAO_MOUNT)')
def test_real_openbao_keeps_a_key_whose_name_is_asked_again():
    provider = OpenBaoProvider({'url': BENCH_URL, 'token': os.environ['UCM_TEST_OPENBAO_TOKEN'],
                                'mount_path': os.environ.get('UCM_TEST_OPENBAO_MOUNT', 'transit')})
    name = f'ucm-pq-test-taken-{uuid.uuid4().hex[:8]}'
    with provider:
        info = provider.generate_key(name, 'ML-DSA-65')
        try:
            for asked in ('ML-DSA-65', 'EC-P256'):
                with pytest.raises(HsmOperationError, match='already exists'):
                    provider.generate_key(name, asked)
            assert _spki(provider.get_public_key(name)) == _spki(info.public_key_pem)
        finally:
            provider.delete_key(name)
